sys_ui_action.script:
// bfd_ui_resolve_case — require the resolution fields, then move the case to
// resolved. The resolution-dates business rule stamps actual_resolution_date
// and the closure/feedback flow handles notification + metric snapshot.
(function resolveCaseAction() {
    var code = current.getValue('resolution_code') || '';
    var summary = current.getValue('resolution_summary') || '';
    var missing = [];

    if (!code) missing.push('Resolution code');
    if (!summary) missing.push('Resolution summary');

    if (missing.length) {
        gs.addErrorMessage(
            'Cannot resolve this case: ' + missing.join(' and ') + ' ' + (missing.length > 1 ? 'are' : 'is') + ' required.'
        );
        action.setRedirectURL(current);
        return;
    }

    current.setValue('case_status', 'resolved');
    new bfd_TriageEngine().logAiDecision(current, {
        note:
            'Case resolved by ' +
            gs.getUserDisplayName() +
            ' with resolution code "' +
            code +
            '".',
        finalDecision: 'case_status=resolved',
    });
    current.update();

    gs.addInfoMessage(
        'Case resolved. The resolution date has been stamped and the customer will be notified with a satisfaction survey.'
    );
    action.setRedirectURL(current);
})();
